using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class CorridorOnlyApply {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/B5/";static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>Repo+"/Docs/검수/2026-11-08_B5_CorridorOnlyGuidance/";static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;
 class Corridor {public string id;public Vector3 a,b,f,right;public float length,half;public float Distance(Vector3 p,int side){var d=p-a;float z=Vector3.Dot(d,f),x=Vector3.Dot(d,right);return side==0?z:side==1?length-z:side==2?half-x:half+x;}public bool Contains(Vector3 p,float eps=0){return Enumerable.Range(0,4).All(i=>Distance(p,i)>=-eps);}}
 struct Vertex {public Vector3 p;public Vector2 uv;public Color color;public static Vertex Lerp(Vertex a,Vertex b,float t)=>new Vertex{p=Vector3.LerpUnclamped(a.p,b.p,t),uv=Vector2.LerpUnclamped(a.uv,b.uv,t),color=Color.LerpUnclamped(a.color,b.color,t)};}
 static List<Vertex> Clip(List<Vertex> src,Corridor c,int side){var dst=new List<Vertex>();if(src.Count==0)return dst;var a=src[src.Count-1];float da=c.Distance(a.p,side);foreach(var b in src){float db=c.Distance(b.p,side);if((da>=0)!=(db>=0))dst.Add(Vertex.Lerp(a,b,da/(da-db)));if(db>=0)dst.Add(b);a=b;da=db;}return dst;}
 static bool Guide(Renderer r){string path=P(r.transform);return r.enabled&&r.gameObject.activeInHierarchy&&r.GetComponent<MeshFilter>()&&(path.Contains("/Spatial_DestinationGuidance/")||path.Contains("/C01_Workplace_Wayfinding/")&&r.bounds.max.y<-81.65f||r.sharedMaterials.Any(m=>m&&new[]{"ND_Label_","ND_Paint_","CW_Paint_","CW_FloorCode_"}.Any(p=>m.name.StartsWith(p)))&&r.bounds.max.y<-81.65f);}
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("Saved B5 Edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;if(root.Find("B5_CorridorOnly_Guidance"))throw new Exception("Already applied");string backup=Path.GetTempPath()+"AfterSeconds_CorridorOnlyApply_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity";EditorSceneManager.SaveScene(s,backup,true);
 var plan=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_CorridorOnlyGuidance/plan.json"));var rooms=(JObject)plan["rooms"];var corridors=new List<Corridor>();foreach(var t in plan["tunnels"]){var ra=rooms[(string)t["a"]];var rb=rooms[(string)t["b"]];var ca=new Vector3((float)ra["x"],-82,-(float)ra["v"]);var cb=new Vector3((float)rb["x"],-82,-(float)rb["v"]);var f=(cb-ca).normalized;var a=ca+f*((float)ra["r"]+.20f);var b=cb-f*((float)rb["r"]+.20f);corridors.Add(new Corridor{id=(string)t["id"],a=a,b=b,f=f,right=Vector3.Cross(Vector3.up,f),length=Vector3.Distance(a,b),half=(float)t["w"]*.5f-.1f});}
 var sources=root.GetComponentsInChildren<Renderer>().Where(Guide).ToArray();var beforeLights=root.GetComponentsInChildren<Light>(true).Select(l=>EditorJsonUtility.ToJson(l)).ToArray();var beforeColliders=root.GetComponentsInChildren<Collider>(true).Select(c=>EditorJsonUtility.ToJson(c)).ToArray();var parent=new GameObject("B5_CorridorOnly_Guidance").transform;parent.SetParent(root,false);parent.position=Vector3.zero;var changes=new List<object>();var counts=corridors.ToDictionary(c=>c.id,c=>0);int num=0,total=0,inside=0,degenerate=0;var leftover=new List<string>();
 foreach(var r in sources){var f=r.GetComponent<MeshFilter>();var src=f.sharedMesh;if(!src.isReadable)throw new Exception("Unreadable "+src.name);var pos=src.vertices.Select(v=>f.transform.TransformPoint(v)).ToArray();var uv=src.uv;var color=src.colors;int sourceTris=src.triangles.Length/3;int kept=0;bool text=r.name.Contains("Label")||r.name.Contains("Legend")||r.name.Contains("Destination")||r.name.Contains("FloorCode")||r.sharedMaterials.Any(m=>m&&m.name.StartsWith("ND_Label_"));
 foreach(var c in corridors){if(text&&!pos.All(v=>c.Contains(v,.00001f)))continue;var vv=new List<Vector3>();var uu=new List<Vector2>();var cc=new List<Color>();var sub=new List<int>[src.subMeshCount];for(int sm=0;sm<src.subMeshCount;sm++){sub[sm]=new List<int>();var ts=src.GetTriangles(sm);for(int i=0;i<ts.Length;i+=3){var poly=new List<Vertex>();for(int k=0;k<3;k++){int j=ts[i+k];poly.Add(new Vertex{p=pos[j],uv=uv.Length==pos.Length?uv[j]:Vector2.zero,color=color.Length==pos.Length?color[j]:Color.white});}for(int side=0;side<4&&poly.Count>0;side++)poly=Clip(poly,c,side);if(poly.Count<3)continue;for(int k=1;k<poly.Count-1;k++){var tri=new[]{poly[0],poly[k],poly[k+1]};if(Vector3.Cross(tri[1].p-tri[0].p,tri[2].p-tri[0].p).sqrMagnitude<1e-17f)continue;int start=vv.Count;foreach(var v in tri){vv.Add(v.p);uu.Add(v.uv);cc.Add(v.color);}sub[sm].AddRange(new[]{start,start+1,start+2});}}}if(vv.Count==0)continue;
 var mesh=new Mesh{name="CG_"+num.ToString("000")+"_"+c.id.Substring(3)+"_"+r.name,indexFormat=IndexFormat.UInt32};mesh.SetVertices(vv);mesh.SetUVs(0,uu);if(color.Length>0)mesh.SetColors(cc);mesh.subMeshCount=sub.Length;for(int sm=0;sm<sub.Length;sm++)mesh.SetTriangles(sub[sm],sm);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,E+mesh.name+".asset");var g=new GameObject(mesh.name);g.transform.SetParent(parent,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;var rr=g.AddComponent<MeshRenderer>();rr.sharedMaterials=r.sharedMaterials;rr.shadowCastingMode=ShadowCastingMode.Off;rr.receiveShadows=r.receiveShadows;rr.reflectionProbeUsage=ReflectionProbeUsage.Off;rr.lightProbeUsage=r.lightProbeUsage;int n=vv.Count/3;counts[c.id]+=n;kept+=n;total+=n;num++;
 // Geometric validation against every dome/core: clipped geometry must lie outside its plan circle.
 for(int i=0;i<vv.Count;i+=3){var center=(vv[i]+vv[i+1]+vv[i+2])/3;foreach(var room in rooms){float dx=center.x-(float)room.Value["x"],dz=center.z+(float)room.Value["v"];if(dx*dx+dz*dz<Mathf.Pow((float)room.Value["r"],2)-.001f)inside++;}if(Vector3.Cross(vv[i+1]-vv[i],vv[i+2]-vv[i]).sqrMagnitude<1e-22f)degenerate++;}
 }r.enabled=false;if(PrefabUtility.IsPartOfPrefabInstance(r))PrefabUtility.RecordPrefabInstancePropertyModifications(r);changes.Add(new{path=P(r.transform),source=AssetDatabase.GetAssetPath(src),sourceTriangles=sourceTris,keptTriangles=kept});}
 bool lightsSame=beforeLights.SequenceEqual(root.GetComponentsInChildren<Light>(true).Select(l=>EditorJsonUtility.ToJson(l)));bool collidersSame=beforeColliders.SequenceEqual(root.GetComponentsInChildren<Collider>(true).Select(c=>EditorJsonUtility.ToJson(c)));if(!lightsSame||!collidersSame||inside!=0||degenerate!=0||counts.Any(c=>c.Value==0))throw new Exception("Corridor validation failed");
 Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var result=new{backup,sources=sources.Length,meshes=num,triangles=total,domeInteriorTriangles=inside,degenerate,lightsSame,collidersSame,corridors=counts,changes,boundaries=corridors.Select(c=>new{c.id,a=new[]{c.a.x,c.a.z},b=new[]{c.b.x,c.b.z},c.half})};File.WriteAllText(O+"apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{sources=sources.Length,meshes=num,triangles=total,domeInteriorTriangles=inside,degenerate,lightsSame,collidersSame,corridors=counts};}
}
